<?php
class Reports {
 static function rows(array $d):array{$type=$d['type']??'daily';staff(in_array($type,['inventory','low_stock','movements'],true)?'inventory':'reports');$from=$d['from']??date('Y-m-01');$to=$d['to']??date('Y-m-d');foreach([$from,$to] as $date)if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))fail('Invalid report date.');$a=[$from,$to.' 23:59:59'];
  if(in_array($type,['inventory','low_stock','movements'],true)){if($type==='movements')return all('SELECT m.created_at,v.sku,m.type,m.quantity,m.reason FROM inventory_movements m JOIN product_variants v ON v.id=m.variant_id WHERE m.created_at BETWEEN ? AND ? ORDER BY m.id DESC LIMIT 1000',$a);return all('SELECT p.name,v.sku,i.physical,i.reserved,i.physical-i.reserved available,v.low_stock FROM inventory_balances i JOIN product_variants v ON v.id=i.variant_id JOIN products p ON p.id=v.product_id'.($type==='low_stock'?' WHERE i.physical-i.reserved<=v.low_stock':'').' ORDER BY p.name LIMIT 1000');}
  if($type==='collections')return all("SELECT DATE(created_at) date,method,SUM(amount) collections FROM (SELECT created_at,method,amount FROM payments WHERE status='confirmed' UNION ALL SELECT created_at,'refund',-amount FROM refunds) p WHERE created_at BETWEEN ? AND ?".(!empty($d['method'])?' AND method=?':'').' GROUP BY DATE(created_at),method ORDER BY date DESC LIMIT 1000',!empty($d['method'])?[...$a,$d['method']]:$a);
  if($type==='outstanding')return all("SELECT o.number,o.name,o.total,COALESCE(p.paid,0) paid,o.total-COALESCE(p.paid,0) outstanding FROM orders o LEFT JOIN (SELECT order_id,SUM(amount) paid FROM payments WHERE status='confirmed' GROUP BY order_id) p ON p.order_id=o.id WHERE o.status<>'cancelled' AND o.total>COALESCE(p.paid,0) ORDER BY o.id DESC LIMIT 1000");
  if($type==='preorders')return all("SELECT o.number,i.name,i.sku,i.quantity,i.expected_date,i.progress,i.total,i.due_now FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.availability='preorder' AND CAST(o.created_at AS DATETIME) BETWEEN ? AND ? ORDER BY o.id DESC LIMIT 1000",$a);
  if($type==='profit')staff('costs');$group=['daily'=>'DATE(o.created_at)','monthly'=>"DATE_FORMAT(o.created_at,'%Y-%m')",'yearly'=>'YEAR(o.created_at)','product'=>'i.name','category'=>'i.category_name','brand'=>'i.brand_name','customer'=>'o.email','best'=>'i.name','profit'=>'DATE(o.created_at)'][$type]??'DATE(o.created_at)';
  $where="o.status='completed' AND CAST(o.created_at AS DATETIME) BETWEEN ? AND ?";foreach(['category'=>'i.category_name','brand'=>'i.brand_name','product'=>'i.product_id','customer'=>'o.customer_id'] as $key=>$col)if(!empty($d[$key])){$where.=" AND $col=?";$a[]=$d[$key];}
  return all("SELECT $group label,SUM(i.quantity) units,SUM(i.total-i.tax) merchandise,SUM(CASE WHEN o.subtotal-o.discount>0 THEN (i.total-i.tax)*COALESCE(r.merch,0)/(o.subtotal-o.discount) ELSE 0 END) refunds,SUM(i.total-i.tax-CASE WHEN o.subtotal-o.discount>0 THEN (i.total-i.tax)*COALESCE(r.merch,0)/(o.subtotal-o.discount) ELSE 0 END) net_sales".($type==='profit'?",SUM(i.unit_cost*i.quantity-CASE WHEN costs.cost>0 THEN i.unit_cost*i.quantity*COALESCE(r.cost,0)/costs.cost ELSE 0 END) net_cost,SUM(i.total-i.tax-i.unit_cost*i.quantity-CASE WHEN o.subtotal-o.discount>0 THEN (i.total-i.tax)*COALESCE(r.merch,0)/(o.subtotal-o.discount) ELSE 0 END+CASE WHEN costs.cost>0 THEN i.unit_cost*i.quantity*COALESCE(r.cost,0)/costs.cost ELSE 0 END) gross_profit":'')." FROM orders o JOIN order_items i ON i.order_id=o.id LEFT JOIN (SELECT order_id,SUM(merchandise_amount) merch,SUM(cost_reversal) cost FROM refunds GROUP BY order_id) r ON r.order_id=o.id LEFT JOIN (SELECT order_id,SUM(unit_cost*quantity) cost FROM order_items GROUP BY order_id) costs ON costs.order_id=o.id WHERE $where GROUP BY $group ORDER BY ".($type==='best'?'units DESC':'label DESC').' LIMIT 1000',$a);
 }
 static function dashboard():array{staff('view');$r=one("SELECT COALESCE(SUM(CASE WHEN status='completed' THEN subtotal-discount ELSE 0 END),0) total_sales,COALESCE(SUM(CASE WHEN status='completed' AND DATE(created_at)=CURRENT_DATE THEN subtotal-discount ELSE 0 END),0) today_sales,COALESCE(SUM(CASE WHEN status='completed' AND DATE_FORMAT(created_at,'%Y-%m')=DATE_FORMAT(NOW(),'%Y-%m') THEN subtotal-discount ELSE 0 END),0) month_sales,SUM(status='pending') pending_orders FROM orders");$r['cash_received']=(int)one("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE status='confirmed'")['n']-(int)one('SELECT COALESCE(SUM(amount),0) n FROM refunds')['n'];$r['customers']=(int)one('SELECT COUNT(*) n FROM customers')['n'];$r['products']=(int)one('SELECT COUNT(*) n FROM products')['n'];$r['low_stock']=(int)one('SELECT COUNT(*) n FROM inventory_balances i JOIN product_variants v ON v.id=i.variant_id WHERE i.physical-i.reserved<=v.low_stock')['n'];$r['out_of_stock']=(int)one('SELECT COUNT(*) n FROM inventory_balances WHERE physical-reserved=0')['n'];$r['preorders']=(int)one("SELECT COUNT(*) n FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.availability='preorder' AND o.status NOT IN ('completed','cancelled')")['n'];$refunds=one("SELECT COALESCE(SUM(r.merchandise_amount),0) total,COALESCE(SUM(CASE WHEN DATE(o.created_at)=CURRENT_DATE THEN r.merchandise_amount ELSE 0 END),0) today,COALESCE(SUM(CASE WHEN DATE_FORMAT(o.created_at,'%Y-%m')=DATE_FORMAT(NOW(),'%Y-%m') THEN r.merchandise_amount ELSE 0 END),0) month FROM refunds r JOIN orders o ON o.id=r.order_id WHERE o.status='completed'");$r['total_sales']-=(int)$refunds['total'];$r['today_sales']-=(int)$refunds['today'];$r['month_sales']-=(int)$refunds['month'];$r['outstanding']=(int)one("SELECT COALESCE(SUM(GREATEST(0,o.total-COALESCE(p.paid,0))),0) n FROM orders o LEFT JOIN (SELECT order_id,SUM(amount) paid FROM payments WHERE status='confirmed' GROUP BY order_id) p ON p.order_id=o.id WHERE o.status<>'cancelled'")['n'];return $r;}
}

